/// The letters and numbers a button can show as a picture, in the order of their slots.
const GLYPHS: &[(char, &[u8])] = &[
    ('A', include_bytes!("art/glyph_a.png")),
    ('B', include_bytes!("art/glyph_b.png")),
    ('C', include_bytes!("art/glyph_c.png")),
    ('E', include_bytes!("art/glyph_e.png")),
    ('F', include_bytes!("art/glyph_f.png")),
    ('L', include_bytes!("art/glyph_l.png")),
    ('M', include_bytes!("art/glyph_m.png")),
    ('N', include_bytes!("art/glyph_n.png")),
    ('O', include_bytes!("art/glyph_o.png")),
    ('P', include_bytes!("art/glyph_p.png")),
    ('S', include_bytes!("art/glyph_s.png")),
    ('T', include_bytes!("art/glyph_t.png")),
    ('V', include_bytes!("art/glyph_v.png")),
    ('X', include_bytes!("art/glyph_x.png")),
    ('Z', include_bytes!("art/glyph_z.png")),
    ('1', include_bytes!("art/glyph_1.png")),
    ('2', include_bytes!("art/glyph_2.png")),
    ('3', include_bytes!("art/glyph_3.png")),
    ('5', include_bytes!("art/glyph_5.png")),
    ('7', include_bytes!("art/glyph_7.png")),
];

/// How many slots the renderer needs: the icons first, then the letters and numbers.
pub const SLOT_COUNT: usize = ICON_COUNT + 20;

/// One picture, cropped to the pixels that are not transparent. `slot` is the icon's number, or
/// `ICON_COUNT` plus the letter's place for a glyph.
#[derive(Clone)]
pub struct Picture {
    pub slot: usize,
    pub width: u32,
    pub height: u32,
    pub rgba: Vec<u8>,
}

/// The slot of the picture of a letter or number, if there is one.
pub fn glyph_slot(ch: char) -> Option<usize> {
    GLYPHS.iter().position(|&(known, _)| known == ch).map(|index| ICON_COUNT + index)
}

/// Every picture, decoded once.
pub fn pictures() -> &'static [Picture] {
    static ALL: std::sync::OnceLock<Vec<Picture>> = std::sync::OnceLock::new();
    ALL.get_or_init(|| {
        let icons = ICONS.iter().map(|&(icon, bytes)| (icon as usize, bytes));
        let glyphs = GLYPHS.iter().enumerate().map(|(index, &(_, bytes))| (ICON_COUNT + index, bytes));
        icons
            .chain(glyphs)
            .filter_map(|(slot, bytes)| {
                let image = image::load_from_memory(bytes).ok()?.to_rgba8();
                crop(slot, image.width(), image.height(), image.as_raw())
            })
            .collect()
    })
}

/// Changes when the pictures do, so the renderer knows when to rebuild its texture. They are built in,
/// so it never changes after the first one.
pub fn version() -> u64 {
    1
}

/// Cuts away the transparent border, so the picture is centred by what it shows. None when the frame
/// is empty or its size does not match its data.
fn crop(slot: usize, width: u32, height: u32, data: &[u8]) -> Option<Picture> {
    let (w, h) = (width as usize, height as usize);
    if w == 0 || h == 0 || data.len() != w * h * 4 {
        return None
    }
    let (mut x0, mut y0, mut x1, mut y1) = (w, h, 0usize, 0usize);
    for y in 0..h {
        for x in 0..w {
            if data[(y * w + x) * 4 + 3] > 8 {
                x0 = x0.min(x);
                y0 = y0.min(y);
                x1 = x1.max(x + 1);
                y1 = y1.max(y + 1);
            }
        }
    }
    if x1 <= x0 || y1 <= y0 {
        return None
    }
    let (cw, ch) = (x1 - x0, y1 - y0);
    let mut rgba = Vec::with_capacity(cw * ch * 4);
    for y in y0..y1 {
        rgba.extend_from_slice(&data[(y * w + x0) * 4..(y * w + x1) * 4]);
    }
    Some(Picture { slot, width: cw as u32, height: ch as u32, rgba })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn crop_keeps_only_the_visible_part() {
        // 4x3 frame with a single opaque pixel at (2, 1).
        let mut data = vec![0u8; 4 * 3 * 4];
        data[(1 * 4 + 2) * 4..(1 * 4 + 2) * 4 + 4].copy_from_slice(&[9, 8, 7, 255]);
        let p = crop(3, 4, 3, &data).unwrap();
        assert_eq!((p.width, p.height), (1, 1));
        assert_eq!(p.rgba, vec![9, 8, 7, 255]);
        assert!(crop(3, 4, 3, &vec![0u8; 48]).is_none(), "an empty frame is no picture");
        assert!(crop(3, 4, 3, &[0u8; 5]).is_none(), "a size that does not match is refused");
    }

    #[test]
    fn every_embedded_picture_decodes_and_fits() {
        assert_eq!(pictures().len(), ICONS.len() + GLYPHS.len(), "every embedded picture must decode");
        assert!(pictures().iter().all(|p| p.width >= 6 && p.height >= 6 && p.width <= 16 && p.height <= 16));
    }

    #[test]
    fn every_icon_has_its_picture_in_its_own_slot() {
        assert_eq!(ICONS.len(), ICON_COUNT, "one picture per icon");
        for (index, &(icon, _)) in ICONS.iter().enumerate() {
            assert_eq!(icon as usize, index, "pictures are listed in the order of the icons");
            assert!(pictures().iter().any(|p| p.slot == icon as usize));
        }
    }

    #[test]
    fn letters_and_numbers_have_a_slot_each() {
        assert_eq!(GLYPHS.len() + ICON_COUNT, SLOT_COUNT);
        for ch in "ZXCVABEFLMNOPST12357".chars() {
            let slot = glyph_slot(ch).unwrap_or_else(|| panic!("no picture for {ch}"));
            assert!(pictures().iter().any(|p| p.slot == slot));
        }
        assert!(glyph_slot('4').is_none());
        assert!(glyph_slot('z').is_none(), "labels are upper case");
    }
}
